CREATE TABLE "Account" ("account_id" INTEGER PRIMARY KEY, "holder_name" TEXT NOT NULL);
CREATE TABLE "Campaign" ("campaign_id" INTEGER PRIMARY KEY, "title" TEXT);
CREATE TABLE "Dispatch_Log" ("campaign_id" INTEGER, "account_id" INTEGER, "status" TEXT, "logged_at" DATETIME, FOREIGN KEY ("campaign_id") REFERENCES "Campaign" ("campaign_id"), FOREIGN KEY ("account_id") REFERENCES "Account" ("account_id"));
